args.ReplacementContent:
@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:wght@300;400;500;600;700&display=swap');

.hero {
  width: 100%;
  background: #111319;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  padding-top: 120px;
  font-family: 'Inter Tight', sans-serif;
}

/* Background Ambient Glows */
.hero-glow {
  position: absolute;
  top: 50%;
  right: 0;
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(163, 230, 53, 0.15) 0%, transparent 60%);
  transform: translateY(-50%);
  pointer-events: none;
  z-index: 0;
}

/* Container */
.hero-container {
  position: relative;
  z-index: 10;
  width: 100%;
  max-width: 1300px;
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr;
  gap: 60px;
  align-items: center;
}

@media (min-width: 1024px) {
  .hero-container {
    grid-template-columns: 1fr 1.1fr;
    gap: 40px;
  }
}

/* Left Content */
.hero-left {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  background: rgba(255, 255, 255, 0.08);
  padding: 6px 16px;
  border-radius: 100px;
  color: #a1a1aa;
  font-size: 13px;
  font-weight: 500;
  width: fit-content;
}

.hero-title {
  font-size: 56px;
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: #ffffff;
  margin: 0;
}

@media (min-width: 1024px) {
  .hero-title {
    font-size: 64px;
  }
}

.hero-desc {
  font-size: 16px;
  line-height: 1.6;
  color: #94a3b8;
  margin: 0;
  max-width: 480px;
}

.hero-btns {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 8px;
}

.btn-primary {
  padding: 14px 28px;
  background: #7c3aed;
  color: #ffffff;
  border: none;
  border-radius: 100px;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s ease;
}

.btn-primary:hover {
  background: #6d28d9;
}

.btn-outline {
  padding: 14px 28px;
  background: transparent;
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 100px;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s ease;
}

.btn-outline:hover {
  background: rgba(255, 255, 255, 0.05);
}

.hero-trust {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 16px;
}

.avatar-group {
  display: flex;
  align-items: center;
}

.avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid #111319;
  margin-right: -12px;
  object-fit: cover;
}

.avatar-count {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid #111319;
  background: rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #e2e8f0;
  font-size: 11px;
  font-weight: 600;
  margin-left: 2px;
  z-index: 1;
}

.trust-text {
  display: flex;
  flex-direction: column;
  font-size: 13px;
}

.trust-bold {
  color: #ffffff;
  font-weight: 600;
}

.trust-light {
  color: #64748b;
}

/* Right Dashboard / Cards */
.hero-right {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 500px;
}

.dashboard-wrapper {
  position: relative;
  width: 100%;
  max-width: 600px;
  height: 100%;
}

.dash-card {
  position: absolute;
  border-radius: 16px;
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.4);
}

/* Card 1: Drop Zone */
.card-dark {
  top: 20px;
  left: 0;
  width: 380px;
  height: 240px;
  background: #171923;
  border: 1px dashed rgba(255, 255, 255, 0.15);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  z-index: 1;
  border-radius: 20px;
}

.drop-icon {
  width: 48px;
  height: 48px;
  background: #ffffff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.drop-text {
  color: #94a3b8;
  font-size: 14px;
  text-align: center;
  line-height: 1.4;
}

.yellow-tag {
  position: absolute;
  top: 30px;
  right: 50px;
  background: #fde047;
  color: #000;
  font-size: 10px;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: 20px;
  z-index: 2;
}

.cursor-icon {
  position: absolute;
  top: 45px;
  right: 35px;
  z-index: 3;
}

/* Card 2: White AI Card */
.card-white {
  bottom: 60px;
  left: 0;
  width: 340px;
  height: 140px;
  background: #ffffff;
  padding: 24px;
  z-index: 4;
  border-radius: 20px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.ai-title {
  font-size: 18px;
  font-weight: 600;
  color: #111;
  margin: 0 0 16px 0;
}

.ai-btn {
  padding: 8px 20px;
  background: #111;
  color: #fff;
  border: none;
  border-radius: 100px;
  font-weight: 500;
  font-size: 13px;
  cursor: pointer;
  width: fit-content;
}

.purple-shapes {
  position: absolute;
  right: -20px;
  bottom: -20px;
  width: 140px;
  height: 140px;
  pointer-events: none;
}

/* Folders Stack */
.folder-stack {
  position: absolute;
  top: 50px;
  right: -40px;
  width: 300px;
  height: 300px;
  z-index: 2;
}

.folder {
  position: absolute;
  width: 260px;
  height: 180px;
  border-radius: 16px;
  box-shadow: -8px 16px 32px rgba(0, 0, 0, 0.3);
}

/* Tab shape for folders */
.folder::before {
  content: '';
  position: absolute;
  top: -16px;
  left: 0;
  width: 100px;
  height: 32px;
  background: inherit;
  border-radius: 12px 12px 0 0;
  z-index: -1;
}

.folder-1 {
  top: 0;
  right: 0;
  background: #c4b5fd;
  transform: rotate(15deg);
  z-index: 1;
}

.folder-2 {
  top: 20px;
  right: 20px;
  background: #ffffff;
  transform: rotate(5deg);
  z-index: 2;
  display: flex;
  padding: 24px;
}

.folder-2 .f-icon {
  width: 32px;
  height: 32px;
  background: #bef264;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-left: auto;
}

.folder-3 {
  top: 40px;
  right: 40px;
  background: #111;
  border: 1px solid rgba(255, 255, 255, 0.1);
  transform: rotate(-5deg);
  z-index: 3;
  padding: 20px;
  display: flex;
  flex-direction: column;
}

.f3-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.f3-header svg {
  color: #fff;
}

.f3-info {
  flex: 1;
}

.f3-title {
  color: #fff;
  font-size: 16px;
  font-weight: 600;
  margin: 0;
}

.f3-sub {
  color: #a1a1aa;
  font-size: 12px;
  margin: 0;
}

.f3-btn {
  width: 32px;
  height: 32px;
  background: #27272a;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.f3-footer {
  margin-top: auto;
  background: #ffffff;
  color: #111;
  padding: 10px 16px;
  border-radius: 100px;
  font-size: 12px;
  font-weight: 500;
  text-align: center;
}

/* Partners Section */
.hero-partners {
  margin-top: 80px;
  padding: 40px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  border-top: 1px solid rgba(255,255,255,0.05);
}

.partners-title {
  color: #cbd5e1;
  font-size: 14px;
  margin-bottom: 24px;
}

.partners-logos {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 40px;
  opacity: 0.5;
}

.partner-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  font-size: 20px;
  font-weight: 600;
}

@media (max-width: 768px) {
  .hero-container {
    grid-template-columns: 1fr;
  }
  .hero-right {
    height: 400px;
  }
  .dashboard-wrapper {
    transform: scale(0.8);
    transform-origin: center top;
  }
}

@media (max-width: 480px) {
  .hero-right {
    height: 320px;
  }
  .dashboard-wrapper {
    transform: scale(0.6);
  }
}

