  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #e2e8f0;
  font-size: 13px;
  font-weight: 600;
  margin-left: 2px;
}

.trust-text {
  display: flex;
  flex-direction: column;
  font-size: 14px;
}

.trust-bold {
  color: #ffffff;
  font-weight: 600;
}

.trust-light {
  color: #94a3b8;
}

/* ============================================
   Right Dashboard
============================================ */
.hero-right {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-end; /* Pushes visuals to the right */
  width: 100%;
  height: 600px;
}

.dashboard-wrapper {
  position: relative;
  width: 100%;
  max-width: 680px;
  height: 100%;
}

.dash-card {
  position: absolute;
  border-radius: 24px;
  box-shadow: 0 40px 80px rgba(0, 0, 0, 0.7);
}

/* --- CARD 1: Dark Drop Zone --- */
.card-dark.drop-zone {
  top: 0;
  left: 0;
  width: 100%;
  max-width: 480px;
  height: 300px;
  background: #161e2b;
  border: 1px dashed rgba(255, 255, 255, 0.1);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  z-index: 1;
}

.drop-text {
  color: #94a3b8;
  font-size: 16px;
  text-align: center;
  line-height: 1.5;
}

.yellow-tag {
  position: absolute;
  top: 30px;
  right: 30px;
  background: #fde047;
  color: #000;
  font-size: 12px;
  font-weight: 600;
  padding: 6px 16px;
  border-radius: 20px;
}

.cursor-icon {
  position: absolute;
  top: 55px;
  right: 10px;
  transform: rotate(-15deg);
}

/* --- CARD 2: White AI Card --- */
.card-white {
  bottom: 20px;
  left: 0px;
  width: 100%;
  max-width: 420px;
  height: 200px;
  background: #ffffff;
  padding: 30px;
  z-index: 2;
  overflow: hidden;
}

.ai-title {
  font-size: 24px;
  font-weight: 700;
  color: #000000;
  margin: 0 0 12px 0;
}

.ai-btn {
  padding: 12px 28px;
  background: #0f172a;
  color: #ffffff;
  border: none;
  border-radius: 100px;
  font-weight: 500;
  font-size: 15px;
  cursor: pointer;
  width: fit-content;
}

.ai-btn:hover {
  background: #1e293b;
}

/* Purple Glass Shards */
.purple-shard {
  position: absolute;
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(167, 139, 250, 0.4), rgba(139, 92, 246, 0.15));
  backdrop-filter: blur(4px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  pointer-events: none;
}

.s1 { width: 80px; height: 100px; transform: rotate(15deg); bottom: -10px; right: 60px; background: linear-gradient(135deg, rgba(196, 181, 253, 0.5), rgba(139, 92, 246, 0.2)); }
.s2 { width: 50px; height: 120px; transform: rotate(-10deg); bottom: 20px; right: 0px; background: linear-gradient(135deg, rgba(167, 139, 250, 0.3), rgba(99, 102, 241, 0.1)); }
.s3 { width: 100px; height: 50px; transform: rotate(45deg); bottom: 40px; right: 100px; background: linear-gradient(135deg, rgba(196, 181, 253, 0.3), rgba(139, 92, 246, 0.2)); }

/* --- CARD 3: Purple Background Tag --- */
.card-purple-tag {
  top: 60px;
  right: 30px;
  width: 200px;
  height: 280px;
  background: linear-gradient(135deg, #a78bfa, #8b5cf6);
  transform: rotate(-8deg);
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.tag-text {
  font-size: 32px;
  color: #ffffff;
}

/* --- CARD 4: Black Photo Card --- */
.card-black {
  top: 130px;
  right: -10px;
  width: 100%;
  max-width: 340px;
  height: 210px;
  background: #0f172a;
  padding: 24px;
  z-index: 3;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.photo-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.photo-info {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.photo-name {
  font-size: 16px;
  font-weight: 600;
  color: #ffffff;
}

.photo-count {
  font-size: 13px;
  color: #94a3b8;
}

.photo-dots {
  color: #94a3b8;
  font-size: 20px;
  cursor: pointer;
  letter-spacing: 1px;
}

.photo-footer {
  margin-top: 55px;
  background: rgba(255, 255, 255, 0.05);
  padding: 12px 16px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.photo-footer span {
  color: #e2e8f0;
  font-size: 14px;
}

/* --- CARD 5: Red Side Tab --- */
.card-red {
  top: 55%;
  right: -10px;
  transform: translateY(-50%) rotate(-90deg);
  transform-origin: center center;
  width: 160px;
  height: 50px;
  background: #ef4444;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  z-index: 4;
  border-radius: 12px 12px 0 0;
  box-shadow: 0 10px 30px rgba(239, 68, 68, 0.3);
}

.card-red span {
  color: #ffffff;
  font-weight: 600;
  font-size: 14px;
  white-space: nowrap;
}

.red-dots {
  color: #ffffff;
  font-size: 16px;
  letter-spacing: 2px;
}

/* ============================================
   Responsive (Mobile)
============================================ */
@media (max-width: 1024px) {
  .card-black { top: 100px; }
  .card-white { left: -20px; max-width: 380px; }
  .dashboard-wrapper { max-width: 580px; }
}

@media (max-width: 768px) {
  .hero-container {
    grid-template-columns: 1fr;
    gap: 40px;
    padding: 0 15px;
  }

  .hero-btns {
    flex-direction: column;
    width: 100%;
  }

  .btn-primary, .btn-outline {
    width: 100%;
    justify-content: center;
    text-align: center;
  }

  .hero-right {
    height: 400px;
    justify-content: center;
  }

  .dashboard-wrapper {
    max-width: 400px;
    transform: scale(0.6);
    transform-origin: top center;
    margin: -40px 0;
  }

  .card-red, .card-purple-tag {
    display: none;
  }
}

@media (max-width: 480px) {
  .hero-right {
    height: 350px;
  }
  .dashboard-wrapper {
    transform: scale(0.45);
    transform-origin: top left;
    margin: -60px 0 -60px -80px;
  }
}

