@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:wght@300;400;500;600;700&display=swap');

.stats-section {
  background: #0f111a;
  padding: 80px 5% 100px;
  font-family: 'Inter Tight', sans-serif;
  overflow: hidden;
}

.stats-track-wrapper {
  width: 100%;
  overflow: hidden;
  position: relative;
  -webkit-mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
  mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
}

.stats-track {
  display: flex;
  gap: 20px;
  width: max-content;
  animation: statsScroll 30s linear infinite;
}

.stats-track:hover {
  animation-play-state: paused;
}

@keyframes statsScroll {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ── Card ── */
.stat-card {
  flex-shrink: 0;
  width: 240px;
  min-height: 180px;
  background: #151720;
  border: 1px solid #1e2130;
  border-radius: 18px;
  padding: 28px 26px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: background 0.4s ease, border-color 0.4s ease, transform 0.3s ease, box-shadow 0.4s ease;
}

/* Blue corner glow — hidden by default */
.stat-card::before {
  content: '';
  position: absolute;
  top: -60px;
  right: -60px;
  width: 140px;
  height: 140px;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.55) 0%, transparent 70%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
  border-radius: 50%;
}

/* Featured first card always has glow */
.stat-card.featured {
  background: radial-gradient(circle at top right, rgba(43, 62, 200, 0.55) 0%, #151720 65%);
  border-color: #2a3260;
}

.stat-card.featured .stat-value {
  color: #e0cc5a;
}

.stat-card.featured::before {
  opacity: 1;
}

/* Hover state: dark → slightly lighter + blue corner glow */
.stat-card:hover {
  background: #1e2235;
  border-color: #3b4080;
  transform: translateY(-6px);
  box-shadow: 0 20px 50px rgba(99, 102, 241, 0.18);
}

.stat-card:hover::before {
  opacity: 1;
}

/* ── Typography ── */
.stat-label {
  font-size: 13px;
  font-weight: 400;
  color: #6c7280;
  margin-bottom: 8px;
  letter-spacing: 0.01em;
}

.stat-value {
  font-size: 40px;
  font-weight: 500;
  color: #ffffff;
  line-height: 1;
  letter-spacing: -1.5px;
  transition: color 0.3s ease;
}

.stat-card:hover .stat-value {
  color: #a5b4fc;
}

.stat-desc {
  font-size: 12px;
  color: #3d4155;
  margin-top: auto;
  padding-top: 24px;
  line-height: 1.4;
}

/* Entry animation — cards fade+slide in on first load */
.stats-track .stat-card {
  opacity: 0;
  animation: cardEnter 0.6s ease forwards;
}

.stats-track .stat-card:nth-child(1)  { animation-delay: 0.05s; }
.stats-track .stat-card:nth-child(2)  { animation-delay: 0.12s; }
.stats-track .stat-card:nth-child(3)  { animation-delay: 0.19s; }
.stats-track .stat-card:nth-child(4)  { animation-delay: 0.26s; }
.stats-track .stat-card:nth-child(5)  { animation-delay: 0.33s; }
.stats-track .stat-card:nth-child(6)  { animation-delay: 0.05s; }
.stats-track .stat-card:nth-child(7)  { animation-delay: 0.12s; }
.stats-track .stat-card:nth-child(8)  { animation-delay: 0.19s; }
.stats-track .stat-card:nth-child(9)  { animation-delay: 0.26s; }
.stats-track .stat-card:nth-child(10) { animation-delay: 0.33s; }

@keyframes cardEnter {
  from { opacity: 0; transform: translateY(30px); }
  to   { opacity: 1; transform: translateY(0); }
}

@media (max-width: 768px) {
  .stats-section {
    padding: 60px 0 80px;
  }
  .stat-card {
    width: 200px;
    min-height: 160px;
    padding: 22px 20px;
  }
  .stat-value {
    font-size: 32px;
  }
}

