@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:wght@300;400;500;600;700&display=swap');

.signup-section {
  background: #0d0f18;
  color: #ffffff;
  padding: 100px 7%;
  font-family: 'Inter Tight', sans-serif;
}

.signup-container {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: start;
}

/* ── Left: Heading + FAQ accordion ── */
.signup-left {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.signup-eyebrow {
  font-size: 13px;
  font-weight: 500;
  color: #5a6278;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 18px;
}

.signup-heading {
  font-size: 48px;
  font-weight: 500;
  line-height: 1.1;
  letter-spacing: -1.5px;
  margin-bottom: 12px;
  color: #ffffff;
}

.signup-heading span {
  color: #5a6278;
}

.signup-subheading {
  font-size: 15px;
  color: #5a6278;
  line-height: 1.6;
  margin-bottom: 50px;
  max-width: 360px;
  text-align: center;
  align-self: center;
}

/* FAQ accordion */
.faq-list {
  display: flex;
  flex-direction: column;
  border-top: 1px solid #1c1f2e;
}

.faq-item {
  border-bottom: 1px solid #1c1f2e;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  color: #d0d4e8;
  font-size: 14px;
  font-weight: 500;
  font-family: 'Inter Tight', sans-serif;
  padding: 20px 4px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  text-align: left;
  transition: color 0.2s ease;
  gap: 16px;
}

.faq-question:hover {
  color: #ffffff;
}

.faq-icon {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  border: 1px solid #2e3350;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #5a6278;
  font-size: 16px;
  line-height: 1;
  transition: border-color 0.2s, color 0.2s, transform 0.3s;
}

.faq-item.open .faq-icon {
  border-color: #3275db;
  color: #3275db;
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
  font-size: 13.5px;
  color: #5a6278;
  line-height: 1.7;
  padding: 0 4px;
}

.faq-item.open .faq-answer {
  max-height: 200px;
  padding: 0 4px 20px;
}

/* ── Right: Form Card ── */
.signup-right {
  position: sticky;
  top: 100px;
}

.signup-card {
  border-radius: 20px;
  padding: 3px;
  background: linear-gradient(145deg, #2067BD, #3275DB, #1a4fa0);
  box-shadow: 0 30px 80px rgba(32, 103, 189, 0.35), 0 0 0 1px rgba(50, 117, 219, 0.2);
  animation: cardPulse 4s ease-in-out infinite;
}

@keyframes cardPulse {
  0%, 100% { box-shadow: 0 30px 80px rgba(32, 103, 189, 0.35), 0 0 0 1px rgba(50, 117, 219, 0.2); }
  50%       { box-shadow: 0 30px 100px rgba(32, 103, 189, 0.55), 0 0 0 1px rgba(50, 117, 219, 0.4); }
}

.signup-card-inner {
  background: #111520;
  border-radius: 18px;
  padding: 36px 32px;
}

.card-title {
  font-size: 22px;
  font-weight: 600;
  color: #ffffff;
  margin-bottom: 6px;
}

.card-subtitle {
  font-size: 13px;
  color: #5a6278;
  margin-bottom: 28px;
  line-height: 1.5;
}

.signup-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.signup-form input,
.signup-form textarea,
.signup-form select {
  width: 100%;
  background: #0d0f18;
  border: 1px solid #1e2235;
  border-radius: 10px;
  padding: 14px 16px;
  color: #c8cedf;
  font-size: 14px;
  font-family: 'Inter Tight', sans-serif;
  outline: none;
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
  resize: none;
  box-sizing: border-box;
}

.signup-form input::placeholder,
.signup-form textarea::placeholder {
  color: #3a3f55;
}

.signup-form input:focus,
.signup-form textarea:focus,
.signup-form select:focus {
  border-color: #3275db;
  box-shadow: 0 0 0 3px rgba(50, 117, 219, 0.12);
}

.signup-form textarea {
  height: 130px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.signup-btn {
  width: 100%;
  background: #ffffff;
  color: #111;
  border: none;
  border-radius: 50px;
  padding: 15px;
  font-size: 15px;
  font-weight: 600;
  font-family: 'Inter Tight', sans-serif;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 6px;
  transition: background 0.25s ease, transform 0.2s ease, box-shadow 0.25s ease;
}

.signup-btn:hover {
  background: #f0f4ff;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(255,255,255,0.15);
}

.signup-btn svg {
  transition: transform 0.2s ease;
}
.signup-btn:hover svg {
  transform: translateX(3px);
}

/* entry animation */
.signup-card {
  opacity: 0;
  animation: cardEnterSignup 0.7s 0.3s ease forwards, cardPulse 4s 1s ease-in-out infinite;
}

@keyframes cardEnterSignup {
  from { opacity: 0; transform: translateY(30px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Responsive */
@media (max-width: 1024px) {
  .signup-container {
    grid-template-columns: 1fr;
    gap: 60px;
  }
  .signup-right {
    position: static;
  }
  .signup-heading {
    font-size: 36px;
    text-align: center;
  }
  .signup-eyebrow { text-align: center; }
}

@media (max-width: 576px) {
  .signup-section { padding: 60px 5%; }
  .signup-heading { font-size: 28px; }
  .form-row { grid-template-columns: 1fr; }
  .signup-card-inner { padding: 24px 20px; }
}

import { useState } from 'react'
import './SignUp.css'

const faqs = [
  {
    q: 'How can I apply for a job at Ezitech?',
    a: 'Fill out the application form with your details, resume, and a brief cover message. Our HR team reviews all submissions within 48 hours.'
  },
  {
    q: 'Are internships available for fresh graduates?',
    a: 'Yes! We offer structured internship programmes across development, design, and AI tracks — open to students and fresh graduates alike.'
  },
  {
    q: 'What is the interview process like?',
    a: 'Our process involves a screening call, a technical assessment, and a final culture-fit interview — usually completed within two weeks.'
  },
  {
    q: 'Do you offer remote or hybrid positions?',
    a: 'Several of our roles support remote or hybrid arrangements depending on the team. The job listing will specify the work model.'
  },
  {
    q: 'Can beginners with no experience apply?',
    a: 'Absolutely. Our "For Beginners" track is designed for motivated individuals starting their tech journey. We provide mentorship and onboarding support.'
  },
  {
    q: 'How long does the hiring decision take?',
    a: 'After completing all interview stages, candidates typically receive an offer letter or decision within 5–7 business days.'
  },
  {
    q: 'Is there a training period after joining?',
    a: 'Yes. All new hires go through a 30-day onboarding programme to get familiar with our tech stack, processes, and team culture.'
  },
]

export default function SignUp() {
  const [openIndex, setOpenIndex] = useState(4)
  const [form, setForm] = useState({ name: '', email: '', subject: '', message: '' })

  const toggle = (i) => setOpenIndex(openIndex === i ? null : i)

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value })

  return (
    <section className="signup-section">
      <div className="signup-container">

        {/* ── Left: Heading + FAQ ── */}
        <div className="signup-left" data-opai-animate data-delay="0.1">
          <p className="signup-eyebrow">FAQs</p>
          <h2 className="signup-heading">
            Your questions,&nbsp;<span>answered</span>
          </h2>
          <p className="signup-subheading">
            Explore our most frequently asked questions to get started.
          </p>

          <div className="faq-list">
            {faqs.map((faq, i) => (
              <div key={i} className={`faq-item${openIndex === i ? ' open' : ''}`}>
                <button className="faq-question" onClick={() => toggle(i)}>
                  {faq.q}
                  <span className="faq-icon">+</span>
                </button>
                <div className="faq-answer">{faq.a}</div>
              </div>
            ))}
          </div>
        </div>

        {/* ── Right: Form Card ── */}
        <div className="signup-right">
          <div className="signup-card">
            <div className="signup-card-inner">
              <h3 className="card-title">Apply according to your experience</h3>
              <p className="card-subtitle">
                Submit your details and our team will match you with the right opportunity.
              </p>

              <form className="signup-form" onSubmit={(e) => e.preventDefault()}>
                <input
                  type="text"
                  name="name"
                  placeholder="Your name"
                  value={form.name}
                  onChange={handleChange}
                />
                <input
                  type="email"
                  name="email"
                  placeholder="Your email"
                  value={form.email}
                  onChange={handleChange}
                />
                <input
                  type="text"
                  name="subject"
                  placeholder="Subject"
                  value={form.subject}
                  onChange={handleChange}
                />
                <textarea
                  name="message"
                  placeholder="Your message or cover note..."
                  value={form.message}
                  onChange={handleChange}
                />

                <button type="submit" className="signup-btn">
                  Contact us
                  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M5 12H19M12 5l7 7-7 7" />
                  </svg>
                </button>
              </form>
            </div>
          </div>
        </div>

      </div>
    </section>
  )
}

