  justify-content: space-between;
  cursor: pointer;
  text-align: left;
  gap: 14px;
  transition: color 0.2s;
}

.faq-question:hover { color: #ffffff; }

.faq-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border: 1px solid #2e3350;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #5a6278;
  font-size: 15px;
  transition: border-color 0.25s, color 0.25s, transform 0.3s;
}

.faq-item.open .faq-icon {
  border-color: #3275db;
  color: #3275db;
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
  font-size: 13px;
  color: #5a6278;
  line-height: 1.7;
  padding: 0 2px;
}

.faq-item.open .faq-answer {
  max-height: 180px;
  padding: 0 2px 16px;
}

/* ── RIGHT: Form Card ── */
.signup-right {
  position: sticky;
  top: 100px;
}

/* Card outer — gradient border effect at bottom corner */
.signup-card {
  border-radius: 20px;
  overflow: hidden;
  position: relative;
  background: #17192a;
  border: 1px solid #232640;
  box-shadow:
    0 25px 70px rgba(32, 103, 189, 0.22),
    0 0 0 1px rgba(50, 117, 219, 0.12);
  animation: cardFadeIn 0.7s 0.3s ease both;
}

/* Bottom-left gradient glow (blue → purple) */
.signup-card::before {
  content: '';
  position: absolute;
  bottom: -40px;
  left: -40px;
  width: 320px;
  height: 220px;
  background: radial-gradient(
    ellipse 65% 60% at 20% 90%,
    rgba(32, 103, 189, 0.6) 0%,
    rgba(50, 117, 219, 0.35) 35%,
    rgba(100, 60, 200, 0.2) 60%,
    transparent 80%
  );
  pointer-events: none;
  z-index: 0;
  border-radius: 50%;
  filter: blur(20px);
}

/* Bottom-right subtle glow */
.signup-card::after {
  content: '';
  position: absolute;
  bottom: -20px;
  right: -20px;
  width: 200px;
  height: 160px;
  background: radial-gradient(
    ellipse at center,
    rgba(100, 60, 200, 0.4) 0%,
    rgba(50, 117, 219, 0.15) 50%,
    transparent 75%
  );
  pointer-events: none;
  z-index: 0;
  filter: blur(16px);
}

.signup-card-inner {
  position: relative;
  z-index: 1;
  padding: 32px 28px 28px;
}

@keyframes cardFadeIn {
  from { opacity: 0; transform: translateY(28px); }
  to   { opacity: 1; transform: translateY(0); }
}

.card-title {
  font-size: 20px;
  font-weight: 600;
  color: #ffffff;
  margin: 0 0 6px;
}

.card-subtitle {
  font-size: 12.5px;
  color: #5a6278;
  margin: 0 0 24px;
  line-height: 1.5;
}

/* ── Form inputs ── */
.signup-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.signup-form input,
.signup-form textarea {
  width: 100%;
  background: #0f1120;
  border: 1px solid #222540;
  border-radius: 8px;
  padding: 13px 15px;
  color: #c8cedf;
  font-size: 13.5px;
  font-family: 'Inter Tight', sans-serif;
  outline: none;
  transition: border-color 0.25s, box-shadow 0.25s;
  resize: none;
  box-sizing: border-box;
}

.signup-form input::placeholder,
.signup-form textarea::placeholder {
  color: #3a3f55;
}

.signup-form input:focus,
.signup-form textarea:focus {
  border-color: #3275db;
  box-shadow: 0 0 0 3px rgba(50, 117, 219, 0.12);
}

.signup-form textarea {
  height: 140px;
}

.signup-btn {
  width: 100%;
  background: #ffffff;
  color: #111;
  border: none;
  border-radius: 50px;
  padding: 14px;
  font-size: 14.5px;
  font-weight: 600;
  font-family: 'Inter Tight', sans-serif;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin-top: 6px;
  transition: background 0.25s, transform 0.2s, box-shadow 0.25s;
}

.signup-btn:hover {
  background: #eef1ff;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(255,255,255,0.12);
}

.signup-btn svg {
  transition: transform 0.2s;
}
.signup-btn:hover svg { transform: translateX(3px); }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .signup-container {
    grid-template-columns: 1fr;
    gap: 50px;
  }
  .signup-right { position: static; }
  .signup-heading { font-size: 36px; }
}

@media (max-width: 576px) {
  .signup-section { padding: 60px 5% 80px; }
  .signup-heading { font-size: 28px; }
  .signup-card-inner { padding: 22px 18px 20px; }
}

