@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:wght@300;400;500;600;700&display=swap');

.hero {
  width: 100%;
  background: #111319;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  padding-top: 180px;
  padding-bottom: 80px;
  font-family: 'Inter Tight', sans-serif;
}

.hero-glow {
  position: absolute;
  top: -200px;
  left: 50%;
  transform: translateX(-50%);
  width: 900px;
  height: 600px;
  background: radial-gradient(ellipse at center, rgba(32,103,189,0.18) 0%, transparent 65%);
  pointer-events: none;
  z-index: 0;
}

.hero-container {
  position: relative;
  z-index: 10;
  width: 100%;
  max-width: 1300px;
  margin: 0 auto;
  padding: 0 40px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

/* Left */
.hero-left {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.hero-badge {
  display: inline-block;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.08);
  padding: 10px 22px;
  border-radius: 100px;
  width: fit-content;
  color: #cbd5e1;
  font-size: 14px;
  font-weight: 500;
}

.hero-title {
  font-size: 74px;
  font-weight: 400;
  line-height: 1.0;
  letter-spacing: -0.05em;
  color: #ffffff;
  margin: 0;
}

.hero-desc {
  font-size: 17px;
  line-height: 1.65;
  color: #94a3b8;
  margin: 0;
  max-width: 480px;
}

.hero-btns {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 4px;
}

.btn-primary {
  padding: 16px 32px;
  background: linear-gradient(135deg, #2067BD, #3275DB);
  color: #fff;
  border: none;
  border-radius: 100px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s;
  text-decoration: none;
}
.btn-primary:hover { opacity: 0.88; }

.btn-outline {
  padding: 16px 32px;
  background: transparent;
  color: #fff;
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 100px;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: border-color 0.2s;
  text-decoration: none;
}
.btn-outline:hover { border-color: rgba(255,255,255,0.4); }

.hero-trust {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 4px;
}

.avatar-group { display: flex; align-items: center; }

.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid #111319;
  margin-right: -10px;
  object-fit: cover;
}

.avatar-count {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.06);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #e2e8f0;
  font-size: 13px;
  font-weight: 600;
  margin-left: 2px;
}

.trust-text { display: flex; flex-direction: column; font-size: 13px; }
.trust-bold { color: #fff; font-weight: 600; }
.trust-light { color: #94a3b8; }

/* Right Dashboard */
.hero-right {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  width: 100%;
  height: 580px;
}

.dashboard-wrapper {
  position: relative;
  width: 100%;
  max-width: 640px;
  height: 100%;
}

.dash-card {
  position: absolute;
  border-radius: 16px;
  box-shadow: 0 30px 60px rgba(0,0,0,0.7), 0 10px 25px rgba(124,58,237,0.2);
}

/* Card 1: Drop Zone */
.card-dark.drop-zone {
  top: 0; left: 0;
  width: 100%; max-width: 460px;
  height: 280px;
  background: #161e2b;
  border: 1px dashed rgba(255,255,255,0.1);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  z-index: 1;
  border-radius: 20px;
  animation: floatSlow 6s ease-in-out infinite;
}

.drop-icon { color: rgba(255,255,255,0.3); }

.drop-text {
  color: #94a3b8;
  font-size: 15px;
  text-align: center;
  line-height: 1.5;
}

.yellow-tag {
  position: absolute;
  top: 24px; right: 24px;
  background: #fde047;
  color: #000;
  font-size: 12px;
  font-weight: 600;
  padding: 5px 14px;
  border-radius: 20px;
}

/* Card 2: White */
.card-white {
  bottom: 20px; left: 0;
  width: 100%; max-width: 400px;
  height: 190px;
  background: #fff;
  padding: 28px;
  z-index: 2;
  overflow: hidden;
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  animation: floatMedium 5s ease-in-out infinite;
}

.ai-title { font-size: 22px; font-weight: 700; color: #000; margin: 0 0 14px; }

.ai-btn {
  padding: 10px 24px;
  background: #0f172a;
  color: #fff;
  border: none;
  border-radius: 100px;
  font-weight: 500;
  font-size: 14px;
  cursor: pointer;
  width: fit-content;
}

.purple-shard {
  position: absolute;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(167,139,250,0.4), rgba(139,92,246,0.15));
  backdrop-filter: blur(4px);
  border: 1px solid rgba(255,255,255,0.2);
  pointer-events: none;
}
.s1 { width: 70px; height: 90px; transform: rotate(15deg); bottom: -8px; right: 55px; }
.s2 { width: 44px; height: 110px; transform: rotate(-10deg); bottom: 18px; right: 0; }
.s3 { width: 90px; height: 44px; transform: rotate(45deg); bottom: 36px; right: 90px; }

/* Card 3: Purple Tag */
.card-purple-tag {
  top: 50px; right: 20px;
  width: 190px; height: 260px;
  background: linear-gradient(135deg, #a78bfa, #8b5cf6);
  transform: rotate(-8deg);
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: floatFast 7s ease-in-out infinite;
}
.tag-text { font-size: 30px; }

/* Card 4: Black Photo Card */
.card-black {
  top: 120px; right: -10px;
  width: 100%; max-width: 320px;
  height: 200px;
  background: #0f172a;
  padding: 22px;
  z-index: 3;
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: 20px;
}
.photo-header { display: flex; align-items: flex-start; gap: 12px; }
.photo-info { flex: 1; display: flex; flex-direction: column; }
.photo-name { font-size: 15px; font-weight: 600; color: #fff; }
.photo-count { font-size: 12px; color: #94a3b8; }
.photo-dots { color: #94a3b8; font-size: 18px; cursor: pointer; }
.photo-footer {
  margin-top: 50px;
  background: rgba(255,255,255,0.05);
  padding: 10px 14px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.photo-footer span { color: #e2e8f0; font-size: 13px; }

/* Card 5: Red Tab */
.card-red {
  top: 55%; right: -10px;
  transform: translateY(-50%) rotate(-90deg);
  transform-origin: center center;
  width: 150px; height: 46px;
  background: #ef4444;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  z-index: 4;
  border-radius: 10px 10px 0 0;
  box-shadow: 0 10px 30px rgba(239,68,68,0.3);
}
.card-red span { color: #fff; font-weight: 600; font-size: 12px; white-space: nowrap; }
.red-dots { color: #fff; font-size: 14px; letter-spacing: 2px; }

/* Float Animations */
@keyframes floatSlow { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-12px)} }
@keyframes floatMedium { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-18px)} }
@keyframes floatFast { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-8px)} }

/* Partners Section */
.hero-partners {
  position: relative;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: 80px;
  padding: 0 40px;
}

.partners-title {
  color: #cbd5e1;
  font-size: 13px;
  margin-bottom: 32px;
  letter-spacing: 0.04em;
}

.partners-logos-container {
  width: 100%;
  max-width: 1000px;
  overflow: hidden;
  position: relative;
  -webkit-mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
  mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
}

.partners-logos {
  display: flex;
  width: max-content;
  animation: marquee 25s linear infinite;
  gap: 60px;
  opacity: 0.5;
}

@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.partner-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #cbd5e1;
  font-size: 15px;
  font-weight: 600;
  white-space: nowrap;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-container { grid-template-columns: 1fr; gap: 40px; }
  .hero-title { font-size: 52px; }
  .hero-right { height: 420px; justify-content: center; }
  .dashboard-wrapper { max-width: 500px; transform: scale(0.82); transform-origin: top center; }
}
@media (max-width: 768px) {
  .hero { padding-top: 130px; }
  .hero-left { align-items: center; text-align: center; }
  .hero-title { font-size: 40px; }
  .hero-btns { justify-content: center; }
  .hero-right { height: 360px; }
  .dashboard-wrapper { transform: scale(0.65); transform-origin: top center; }
  .card-red, .card-purple-tag { display: none; }
}

@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:wght@400;500;600&display=swap');

.hiw-section {
  background: #ffffff;
  padding: 100px 24px;
  font-family: 'Inter Tight', sans-serif;
  color: #111;
