@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap");

.rank-section {
  background: #0f111a;
  color: white;
  padding: 80px 7%;
  min-height: 100vh;
  font-family: "Inter", sans-serif;
}

.rank-tabs {
  display: flex;
  justify-content: center;
  gap: 50px;
  border-bottom: 1px solid #1c1e2a;
  padding-bottom: 0;
  margin-bottom: 60px;
}

.rank-tabs button {
  background: none;
  border: none;
  color: #7d8293;
  cursor: pointer;
  font-size: 15px;
  font-weight: 500;
  padding-bottom: 18px;
  position: relative;
  transition: color 0.3s ease;
  font-family: "Inter", sans-serif;
}

.rank-tabs .active { color: white; border-bottom: 2px solid #7c3aed; }

.rank-container {
  max-width: 1200px;
  margin: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 80px;
}

/* Left */
.rank-left { flex: 1.1; }

.rank-left h2 {
  font-size: 54px;
  line-height: 1.15;
  font-weight: 500;
  letter-spacing: -1px;
}

.rank-left .description {
  margin-top: 24px;
  color: #7d8293;
  font-size: 16px;
  line-height: 1.6;
  max-width: 460px;
}

.rank-features {
  margin-top: 40px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.feature { display: flex; align-items: flex-start; gap: 20px; }

.feature-icon {
  width: 28px; height: 28px;
  border: 1.5px solid #a1a5b7;
  flex-shrink: 0;
  margin-top: 2px;
}

.icon-cylinder { border-radius: 50% / 30%; position: relative; }
.icon-cylinder::after {
  content: '';
  position: absolute;
  top: 30%; left: -1.5px; right: -1.5px; bottom: 0;
  border: 1.5px solid #a1a5b7;
  border-radius: 50% / 30%;
  border-top: none;
}

.icon-sphere { border-radius: 50%; position: relative; }
.icon-sphere::after {
  content: '';
  position: absolute;
  top: 20%; bottom: 20%; left: 0; right: 0;
  border: 1.5px solid #a1a5b7;
  border-radius: 50%;
  border-left: none; border-right: none;
}

.icon-split { border-radius: 50%; position: relative; }
.icon-split::after {
  content: '';
  position: absolute;
  left: 0; right: 0; top: 45%;
  height: 1.5px;
  background: #a1a5b7;
}

.feature h4 { font-size: 16px; font-weight: 600; margin-bottom: 4px; color: #ffffff; }
.feature span { color: #7d8293; font-size: 14px; }

.rank-btn {
  margin-top: 45px;
  background: transparent;
  border: 1px solid #2e3245;
  color: white;
  padding: 14px 28px;
  border-radius: 50px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  transition: background 0.2s ease;
  font-family: "Inter", sans-serif;
}
.rank-btn:hover { background: #1c1e2a; }

/* Right */
.rank-right {
  flex: 0.9;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}

.person-card {
  width: 380px; height: 440px;
  background: #fcae96;
  border-radius: 32px;
  overflow: hidden;
  position: relative;
  z-index: 2;
}
.person-card img { width: 100%; height: 100%; object-fit: cover; }

.shape-lines { position: absolute; left: -20px; top: 35%; z-index: 1; }
.shape-lines span {
  display: block;
  width: 130px; height: 60px;
  border: 1.5px solid #23252f;
  border-radius: 50%;
  margin-top: -42px;
  transform: rotate(-15deg);
}

/* Floating Card 1 */
.assigned-card {
  position: absolute;
  right: -20px;
  top: 32%;
  background: #ffffff;
  color: #0f111a;
  width: 185px;
  padding: 14px;
  border-radius: 14px;
  box-shadow: 0 20px 40px rgba(0,0,0,0.3);
  z-index: 3;
  animation: floatRank1 6s ease-in-out infinite;
}

@keyframes floatRank1 {
  0%,100% { transform: translateY(0); }
  50%      { transform: translateY(-12px); }
}

.assigned-header { display: flex; justify-content: space-between; align-items: flex-start; }

.avatar-group { display: flex; align-items: center; }

.avatar {
  width: 28px; height: 28px;
  border-radius: 50%;
  border: 2px solid white;
  object-fit: cover;
  background: #edd095;
  margin-left: -8px;
  position: relative;
  z-index: 1;
}
.avatar:first-child { margin-left: 0; z-index: 3; }
.avatar:nth-child(2) { z-index: 2; }
.avatar:nth-child(3) { z-index: 1; }

.avatar-arrow {
  width: 28px; height: 28px;
  background: #e1f541;
  border-radius: 50%;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  border: 2px solid white;
  margin-left: -8px;
  color: #111;
  z-index: 0;
}

.assigned-meta { text-align: right; }
.assigned-meta small { font-size: 11px; color: #7d8293; display: block; }
.assigned-meta h3 { font-size: 24px; font-weight: 600; line-height: 1; margin-top: 2px; }

.stars { font-size: 10px; color: #6366f1; margin: 10px 0; letter-spacing: 1px; }

.card-actions { display: flex; gap: 6px; }
.card-actions button {
  font-size: 9px;
  font-weight: 600;
  padding: 5px 8px;
  border-radius: 20px;
  border: none;
  cursor: pointer;
}
.btn-follow { background: #6366f1; color: white; }
.btn-msg    { background: #0f111a; color: white; }

/* Floating Card 2 */
.earning-card {
  position: absolute;
  right: -30px;
  top: calc(32% + 290px);
  background: #ffffff;
  color: #0f111a;
  width: 320px;
  padding: 18px 22px;
  border-radius: 14px;
  box-shadow: 0 20px 40px rgba(0,0,0,0.3);
  z-index: 4;
  animation: floatRank2 7s ease-in-out infinite;
}

@keyframes floatRank2 {
  0%,100% { transform: translateY(0); }
  50%      { transform: translateY(-16px); }
}

.earning-card small { color: #7d8293; font-size: 12px; font-weight: 500; }
.earning-card h4 { margin-top: 4px; font-size: 22px; font-weight: 600; }

.bar { margin-top: 22px; height: 5px; background: #ededf2; border-radius: 10px; overflow: hidden; }
.fill { height: 100%; background: #6366f1; transition: width 0.5s ease; }

.bar-footer { margin-top: 10px; display: flex; font-size: 11px; font-weight: 500; color: #0f111a; }
.bar-footer span:first-child { color: #7d8293; }
.bar-footer span:nth-child(2) { margin-left: auto; font-weight: 600; }
.percentage { margin-left: 6px; color: #7d8293; }

/* Tab Transition */
.rank-animated-content { animation: fadeInTab 0.5s cubic-bezier(0.4,0,0.2,1) forwards; }

@keyframes fadeInTab {
  0%   { opacity: 0; transform: translateY(15px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* Responsive */
@media (max-width: 1024px) {
  .rank-container { flex-direction: column; gap: 80px; text-align: center; }
  .rank-left .description { margin-inline: auto; }
  .feature { text-align: left; max-width: 400px; margin: 0 auto; }
  .rank-right { margin-top: 20px; width: 100%; }
  .earning-card { right: 10%; }
  .assigned-card { right: 15%; }
}
@media (max-width: 576px) {
  .rank-tabs { gap: 20px; }
  .rank-left h2 { font-size: 36px; }
  .person-card { width: 290px; height: 350px; }
  .earning-card { position: relative; right: auto; bottom: auto; margin: 20px auto 0; width: 100%; max-width: 290px; }
  .assigned-card { display: none; }
}

import './Stats.css'

const stats = [
  { label: 'Response time',   value: '3 min',  desc: 'Average support response',          featured: true  },
  { label: 'Open positions',  value: '40+',    desc: 'Across all departments',             featured: false },
  { label: 'Interns hired',   value: '120+',   desc: 'Turned into full-time employees',    featured: false },
  { label: 'Team members',    value: '250+',   desc: 'Across global offices',              featured: false },
  { label: 'Satisfaction',    value: '97.4%',  desc: 'Employee satisfaction score',        featured: false },
  { label: 'Countries',       value: '18+',    desc: 'Global reach & presence',            featured: false },
]

export default function Stats() {
  const doubled = [...stats, ...stats]

  return (
    <section className="stats-section">
      <div className="stats-track-wrapper">
        <div className="stats-track">
          {doubled.map((s, i) => (
            <div
              key={i}
              className={`stat-card${s.featured && i < stats.length ? ' featured' : ''}`}
            >
              <p className="stat-label">{s.label}</p>
              <p className="stat-value">{s.value}</p>
              <p className="stat-desc">{s.desc}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:wght@300;400;500;600;700&display=swap');

.stats-section {
  background: #0f111a;
  padding: 80px 0 100px;
  font-family: 'Inter Tight', sans-serif;
  overflow: hidden;
}

.stats-track-wrapper {
  width: 100%;
  overflow: hidden;
  position: relative;
  -webkit-mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
  mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
}

.stats-track {
  display: flex;
  gap: 20px;
  width: max-content;
  animation: statsScroll 30s linear infinite;
  padding: 10px 0;
}

.stats-track:hover { animation-play-state: paused; }

@keyframes statsScroll {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* Card */
.stat-card {
  flex-shrink: 0;
  width: 240px;
  min-height: 180px;
  background: #151720;
  border: 1px solid #1e2130;
  border-radius: 18px;
  padding: 28px 26px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: background 0.4s ease, border-color 0.4s ease, transform 0.3s ease, box-shadow 0.4s ease;
  opacity: 0;
  animation: cardEnter 0.6s ease forwards;
}

/* Irregular glow blob — hidden by default */
.stat-card::before {
  content: '';
  position: absolute;
  top: -80px;
  right: -80px;
  width: 200px;
  height: 160px;
  background: radial-gradient(ellipse 70% 55% at 70% 30%,
    rgba(99,102,241,0.6) 0%,
    rgba(67,56,202,0.3) 35%,
    transparent 75%
  );
  opacity: 0;
  transition: opacity 0.5s ease, background 0.5s ease;
  pointer-events: none;
  border-radius: 40% 60% 70% 30% / 50% 40% 60% 50%;
  transform: rotate(-20deg);
  filter: blur(18px);
}

/* Featured card */
.stat-card.featured {
  background: radial-gradient(ellipse 80% 60% at 85% 15%,
    rgba(43,62,200,0.55) 0%,
    rgba(17,19,40,0.8) 55%,
    #151720 80%
  );
  border-color: #2a3260;
}

.stat-card.featured .stat-value { color: #e0cc5a; }
.stat-card.featured::before     { opacity: 1; }

/* Hover — white glow */
.stat-card:hover {
  background: #1e2235;
  border-color: #4a4f80;
  transform: translateY(-6px);
  box-shadow: 0 20px 50px rgba(255,255,255,0.06);
}

.stat-card:hover::before {
  opacity: 1;
  background: radial-gradient(ellipse 65% 50% at 75% 25%,
    rgba(255,255,255,0.45) 0%,
    rgba(200,210,255,0.15) 45%,
    transparent 75%
  );
}

.stat-card:hover .stat-value { color: #a5b4fc; }

/* Typography */
.stat-label {
  font-size: 13px;
  font-weight: 400;
  color: #6c7280;
  margin-bottom: 8px;
  letter-spacing: 0.01em;
}

.stat-value {
  font-size: 40px;
  font-weight: 500;
  color: #ffffff;
  line-height: 1;
  letter-spacing: -1.5px;
  transition: color 0.3s ease;
}

.stat-desc {
  font-size: 12px;
  color: #3d4155;
  margin-top: auto;
  padding-top: 24px;
  line-height: 1.4;
}

/* Staggered entry */
.stats-track .stat-card:nth-child(1)  { animation-delay: 0.05s; }
.stats-track .stat-card:nth-child(2)  { animation-delay: 0.12s; }
.stats-track .stat-card:nth-child(3)  { animation-delay: 0.19s; }
.stats-track .stat-card:nth-child(4)  { animation-delay: 0.26s; }
.stats-track .stat-card:nth-child(5)  { animation-delay: 0.33s; }
.stats-track .stat-card:nth-child(6)  { animation-delay: 0.40s; }
.stats-track .stat-card:nth-child(7)  { animation-delay: 0.05s; }
.stats-track .stat-card:nth-child(8)  { animation-delay: 0.12s; }
.stats-track .stat-card:nth-child(9)  { animation-delay: 0.19s; }
.stats-track .stat-card:nth-child(10) { animation-delay: 0.26s; }
.stats-track .stat-card:nth-child(11) { animation-delay: 0.33s; }
.stats-track .stat-card:nth-child(12) { animation-delay: 0.40s; }

@keyframes cardEnter {
  from { opacity: 0; transform: translateY(30px); }
  to   { opacity: 1; transform: translateY(0); }
}

@media (max-width: 768px) {
  .stats-section { padding: 60px 0 80px; }
  .stat-card { width: 200px; min-height: 160px; padding: 22px 20px; }
  .stat-value { font-size: 32px; }
}

@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:wght@300;400;500;600;700&display=swap');

.signup-section {
  background: #0d0f18;
  color: #ffffff;
  padding: 90px 7% 110px;
  font-family: 'Inter Tight', sans-serif;
}

/* ── Centered top heading ── */
.signup-top-header {
  text-align: center;
  margin-bottom: 60px;
}

.signup-heading {
  font-size: 52px;
  font-weight: 500;
  letter-spacing: -1.5px;
  color: #ffffff;
  margin: 0 0 14px;
}

.signup-heading span { color: #5a6278; }

.signup-subheading {
  font-size: 14px;
  color: #5a6278;
  line-height: 1.65;
  margin: 0;
}

/* ── Two-column grid ── */
.signup-container {
  max-width: 1100px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1.05fr;
  gap: 50px;
  align-items: stretch;
}

/* ── LEFT: FAQ ── */
.signup-left {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.faq-list {
  display: flex;
  flex-direction: column;
  border-top: 1px solid #1c1f2e;
  flex: 1;
}

.faq-item { border-bottom: 1px solid #1c1f2e; }

.faq-question {
  width: 100%;
  background: none;
  border: none;
  color: #c8cedf;
  font-size: 13.5px;
  font-weight: 500;
  font-family: 'Inter Tight', sans-serif;
  padding: 15px 2px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  text-align: left;
  gap: 14px;
  transition: color 0.2s;
}

.faq-question:hover { color: #ffffff; }

.faq-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border: 1px solid #2e3350;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #5a6278;
  font-size: 15px;
  transition: border-color 0.25s, color 0.25s, transform 0.3s;
}

.faq-item.open .faq-icon {
  border-color: #3275db;
  color: #3275db;
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
  font-size: 13px;
  color: #5a6278;
  line-height: 1.7;
  padding: 0 2px;
}

.faq-item.open .faq-answer {
  max-height: 180px;
  padding: 0 2px 16px;
}

/* ── RIGHT: Form Card ── */
.signup-right {
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* Bold bottom gradient matching reference */
.signup-card {
  border-radius: 20px;
  overflow: hidden;
  position: relative;
  flex: 1;
  background: linear-gradient(
    to top,
    #3275DB 0%,
    #2067BD 18%,
    #1a2e6e 36%,
    #17192a 55%,
    #17192a 100%
  );
  border: 1px solid #2a3060;
  box-shadow: 0 25px 70px rgba(32, 103, 189, 0.3);
  animation: cardFadeIn 0.7s 0.3s ease both;
}

@keyframes cardFadeIn {
  from { opacity: 0; transform: translateY(28px); }
  to   { opacity: 1; transform: translateY(0); }
}

.signup-card-inner {
  padding: 32px 28px 28px;
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
}

.card-title {
  font-size: 20px;
  font-weight: 600;
  color: #ffffff;
  margin: 0 0 6px;
}

.card-subtitle {
  font-size: 12.5px;
  color: rgba(255,255,255,0.5);
  margin: 0 0 24px;
  line-height: 1.5;
}

/* ── Form inputs ── */
.signup-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
}

.signup-form input,
.signup-form textarea {
  width: 100%;
  background: #0f1120;
  border: 1px solid #222540;
  border-radius: 8px;
  padding: 13px 15px;
  color: #c8cedf;
  font-size: 13.5px;
  font-family: 'Inter Tight', sans-serif;
  outline: none;
  transition: border-color 0.25s, box-shadow 0.25s;
  resize: none;
  box-sizing: border-box;
}

.signup-form input::placeholder,
.signup-form textarea::placeholder { color: #3a3f55; }

.signup-form input:focus,
.signup-form textarea:focus {
  border-color: #3275db;
  box-shadow: 0 0 0 3px rgba(50, 117, 219, 0.12);
}

.signup-form textarea {
  flex: 1;
  min-height: 130px;
}

.signup-btn {
  width: 100%;
  background: #ffffff;
  color: #111;
  border: none;
  border-radius: 50px;
  padding: 14px;
  font-size: 14.5px;
  font-weight: 600;
  font-family: 'Inter Tight', sans-serif;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin-top: 10px;
  transition: background 0.25s, transform 0.2s, box-shadow 0.25s;
}

.signup-btn:hover {
  background: #eef1ff;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(255,255,255,0.12);
}

.signup-btn svg { transition: transform 0.2s; }
.signup-btn:hover svg { transform: translateX(3px); }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .signup-container { grid-template-columns: 1fr; gap: 50px; }
  .signup-right { height: auto; }
  .signup-card { flex: none; }
  .signup-heading { font-size: 36px; }
}

@media (max-width: 576px) {
  .signup-section { padding: 60px 5% 80px; }
  .signup-heading { font-size: 28px; }
  .signup-card-inner { padding: 22px 18px 20px; }
}
